using System;
using System.Collections;
using UnityEngine;
using UnityEngine.UI;
namespace RollerSort {
 public sealed partial class RollerGame {
  static readonly int[] UnlockLevels={6,8,11};static readonly string[] BoosterNames={"Magnet","Shuffle","Clean Up"},BoosterIcons={"magnet","shuffle","gumball"};
  readonly int[] inventory=new int[3];readonly Text[] inventoryLabels=new Text[3];int selectingBooster=-1;bool magnetRelease;RectTransform boosterHint;
  void LoadBoosters(){for(int i=0;i<3;i++)inventory[i]=PlayerPrefs.GetInt("booster"+i,0);}
  void SaveBoosters(){if(diagnosticsActive)return;for(int i=0;i<3;i++)PlayerPrefs.SetInt("booster"+i,inventory[i]);PlayerPrefs.Save();}
  void DrawBoosters(){for(int i=0;i<3;i++){int index=i;bool unlocked=level>=UnlockLevels[i];var r=unlocked?Button(game,"",new Vector2(-106+i*106,223),new Vector2(83,86),colors[2],()=>Booster(index)):Panel(game,"Locked booster",new Vector2(-106+i*106,223),new Vector2(81,81),new Color32(163,182,172,255));if(!unlocked){r.GetComponent<Image>().raycastTarget=true;r.gameObject.AddComponent<Button>().onClick.AddListener(()=>Booster(index));Picture(r,"lock",new Vector2(0,29),new Vector2(37,45));Label(r,"lvl "+UnlockLevels[i].ToString("00"),new Vector2(0,62),20);}else{Picture(r,BoosterIcons[i],new Vector2(0,39),new Vector2(58,61));var badge=Panel(r,"Inventory",new Vector2(35,76),new Vector2(34,34),inventory[i]>0?colors[1]:colors[2],true);badge.GetComponent<Image>().sprite=Art(inventory[i]>0?"inventory-badge":"inventory-plus");inventoryLabels[i]=Label(badge,inventory[i]>0?inventory[i].ToString():"+",new Vector2(0,17),24,bounds:new Vector2(34,34));}}}
  void UpdateInventory(){for(int i=0;i<3;i++)if(inventoryLabels[i]){inventoryLabels[i].text=inventory[i]>0?inventory[i].ToString():"+";inventoryLabels[i].transform.parent.GetComponent<Image>().sprite=Art(inventory[i]>0?"inventory-badge":"inventory-plus");}}
  IEnumerator UnlockIntroduction(){if(diagnosticsActive)yield break;for(int i=0;i<3;i++){if(level<UnlockLevels[i]||PlayerPrefs.GetInt("intro"+i,0)==1)continue;int index=i;if(inventory[i]==0)inventory[i]=1;SaveBoosters();UpdateInventory();yield return new WaitForSeconds(.35f);var p=Modal(BoosterNames[i]+" Unlocked!",440);Picture(p,BoosterIcons[i],new Vector2(0,146),new Vector2(125,136));Label(p,BoosterDescription(i),new Vector2(0,269),22,bounds:new Vector2(330,106));Button(p,"Try It · Free",new Vector2(0,370),new Vector2(270,65),colors[2],()=>{PlayerPrefs.SetInt("intro"+index,1);PlayerPrefs.Save();Close();Booster(index);},27);yield break;}}
  string BoosterDescription(int index)=>index==0?"Ekrandaki herhangi bir kutuyu seç.\nBilyeleri uygun tepsilere çekilir.":index==1?"Öndeki açık kutuların yerlerini\nkarıştırır; renk sayısı korunur.":"Bantta ve haznede bekleyen bilyeleri\nuygun tepsilere doğru toplar.";
  void Booster(int index){if(won||journey)return;if(level<UnlockLevels[index]){Toast("Bölüm "+UnlockLevels[index]+" ile açılır");return;}if(inventory[index]<=0){var p=Modal(BoosterNames[index],460);Picture(p,BoosterIcons[index],new Vector2(0,144),new Vector2(130,140));Label(p,BoosterDescription(index),new Vector2(0,264),21,bounds:new Vector2(335,100));Button(p,"Get ×3\n1.800 coins",new Vector2(0,380),new Vector2(275,95),colors[2],()=>{if(coins<1800){Label(p,"Yeterli altın yok",new Vector2(0,321),18);return;}coins-=1800;inventory[index]+=3;SaveBoosters();PlayerPrefs.SetInt("coins",coins);PlayerPrefs.Save();coinText.text=FormatCoins();UpdateInventory();Close();},29);Button(p,"×",new Vector2(157,28),new Vector2(42,43),colors[1],Close,31);return;}
   if(index==0){if(selectingBooster==0){selectingBooster=-1;Toast("Mıknatıs iptal edildi");return;}selectingBooster=0;Toast("Mıknatıs: bir kutu seç · tekrar dokunarak iptal et");return;}
   if(index==1){ShuffleAccessible(index);return;}
   if(balls.Count==0){Toast("Önce bilyeleri aç.");return;}inventory[index]--;SaveBoosters();UpdateInventory();foreach(var b in balls)b.magnetic=true;StartCoroutine(CleanAnimation());lastMatchTime=clock;
  }
  IEnumerator ShuffleFront(System.Collections.Generic.List<Box> front){paused=true;Sfx("shuffle",.8f);var positions=new Vector2[front.Count];for(int i=0;i<front.Count;i++)positions[i]=front[i].view.anchoredPosition;var first=front[0];int row=first.row,col=first.col;for(int i=0;i<front.Count-1;i++){front[i].row=front[i+1].row;front[i].col=front[i+1].col;}front[front.Count-1].row=row;front[front.Count-1].col=col;for(float t=0;t<.48f;t+=Time.unscaledDeltaTime){float p=Mathf.Clamp01(t/.48f),ease=p*p*(3-2*p);for(int i=0;i<front.Count;i++){Vector2 target=positions[(i+1)%front.Count];front[i].view.anchoredPosition=Vector2.Lerp(positions[i],target,ease)+Vector2.up*Mathf.Sin(p*Mathf.PI)*24;front[i].view.localRotation=Quaternion.Euler(0,0,Mathf.Sin(p*Mathf.PI)*8);}yield return null;}for(int i=0;i<front.Count;i++){front[i].view.anchoredPosition=positions[(i+1)%front.Count];front[i].view.localRotation=Quaternion.identity;}RefreshSourceAccess(false);paused=false;HapticFeedback.Play(HapticCue.TrayComplete);}
  IEnumerator CleanAnimation(){var machine=Picture(actors,"gumball",new Vector2(0,705),new Vector2(122,142));Sfx("magnet",.7f);for(float t=0;t<.9f;){t+=GameStep;float p=t/.9f;machine.localScale=Vector3.one*(.85f+.15f*Mathf.Sin(p*Mathf.PI));machine.localRotation=Quaternion.Euler(0,0,Mathf.Sin(p*18)*5);yield return null;}Destroy(machine.gameObject);}
  void MagneticStep(){foreach(var b in balls){if(!b.magnetic||b.age<0||b.stage==2)continue;foreach(var t in trays){if(t.color!=b.color||t.count>=3||t.completing)continue;b.stage=2;b.seat=t.count++;b.tray=t;b.age=0;b.seatStart=b.position;break;}}}
 }
}
